CREATE FUNCTION private_isg.publish_emergency_plan(p_company uuid,p_workplace uuid,p_plan uuid,p_scope text,
  p_prepared_on date,p_valid_until date,p_team jsonb,p_asset uuid,p_review_note text,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE owner uuid; plan uuid; next_version integer; review boolean; previous integer;
BEGIN
  owner:=private_isg.module_scope('emergency_plan',p_company,p_workplace,true);
  IF p_scope IS NULL OR p_prepared_on IS NULL OR NOT isfinite(p_prepared_on) OR p_now IS NULL OR
     p_team IS NULL OR jsonb_typeof(p_team)<>'array' OR jsonb_array_length(p_team) NOT BETWEEN 1 AND 200 OR
     (p_valid_until IS NOT NULL AND p_valid_until<=p_prepared_on) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  IF p_asset IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='FILE_STORAGE_UNAVAILABLE'; END IF;
  -- An unverified legal basis stays in review; it is never silently accepted.
  review:=p_review_note IS NULL;
  plan:=coalesce(p_plan,gen_random_uuid());
  SELECT coalesce(max(version),0) INTO previous FROM private_isg.emergency_plan_versions WHERE plan_id=plan;
  IF p_plan IS NOT NULL AND previous=0 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  next_version:=previous+1;
  -- Renewing supersedes the pointer only. The previous row keeps its own scope,
  -- team snapshot, dates and file.
  UPDATE private_isg.emergency_plan_versions SET state='superseded' WHERE plan_id=plan AND state='active';
  INSERT INTO private_isg.emergency_plan_versions(plan_id,version,company_id,owner_id,workplace_id,scope,prepared_on,
      valid_until,team_snapshot,asset_id,needs_review,review_note,created_at)
    VALUES(plan,next_version,p_company,owner,p_workplace,private_isg.text_value(p_scope,300),p_prepared_on,
      p_valid_until,p_team,p_asset,review,p_review_note,p_now);
  RETURN jsonb_build_object('schema_version',1,'plan_id',plan,'version',next_version,'state','active',
    'needs_review',review,'previous_version',nullif(previous,0));
END $$;

REVOKE ALL ON FUNCTION private_isg.publish_emergency_plan(uuid,uuid,uuid,text,date,date,jsonb,uuid,text,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private_isg.plan_drill(p_company uuid,p_workplace uuid,p_plan uuid,p_plan_version integer,
  p_planned_on date,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE drill uuid;
BEGIN
  PERFORM private_isg.module_scope('drill',p_company,p_workplace,true);
  IF p_plan IS NULL OR p_plan_version IS NULL OR p_planned_on IS NULL OR NOT isfinite(p_planned_on) OR p_now IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  PERFORM 1 FROM private_isg.emergency_plan_versions
    WHERE company_id=p_company AND plan_id=p_plan AND version=p_plan_version FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  INSERT INTO private_isg.drill_records(company_id,workplace_id,plan_id,plan_version,planned_on,created_at,updated_at)
    VALUES(p_company,p_workplace,p_plan,p_plan_version,p_planned_on,p_now,p_now) RETURNING drill_id INTO drill;
  -- Planning a drill is not performing one.
  RETURN jsonb_build_object('schema_version',1,'drill_id',drill,'state','planned','performed',false);
END $$;

REVOKE ALL ON FUNCTION private_isg.plan_drill(uuid,uuid,uuid,integer,date,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private_isg.record_drill_result(p_drill uuid,p_performed_on date,p_participants jsonb,
  p_observation text,p_improvement text,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.drill_records; known integer; supplied integer;
BEGIN
  IF p_drill IS NULL OR p_now IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT * INTO entry FROM private_isg.drill_records WHERE drill_id=p_drill FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  PERFORM private_isg.module_gate('drill',true);
  IF entry.state='performed' THEN RETURN jsonb_build_object('schema_version',1,'drill_id',p_drill,'state','performed','replayed',true); END IF;
  IF entry.state<>'planned' OR p_performed_on IS NULL OR NOT isfinite(p_performed_on) OR
     p_participants IS NULL OR jsonb_typeof(p_participants)<>'array' OR
     jsonb_array_length(p_participants) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  -- Participants are this company's own employees; an outside id is refused.
  SELECT count(DISTINCT value) INTO supplied FROM jsonb_array_elements_text(p_participants) AS t(value);
  SELECT count(*) INTO known FROM private_isg.employees e
    WHERE e.company_id=entry.company_id
      AND e.id::text IN (SELECT value FROM jsonb_array_elements_text(p_participants) AS t(value));
  IF known<>supplied THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PARTICIPANT_OUT_OF_SCOPE'; END IF;
  UPDATE private_isg.drill_records SET state='performed',performed_on=p_performed_on,participants=p_participants,
    observation=p_observation,improvement=p_improvement,updated_at=p_now WHERE drill_id=p_drill;
  RETURN jsonb_build_object('schema_version',1,'drill_id',p_drill,'state','performed','performed_on',p_performed_on,
    'participants',supplied,'replayed',false);
END $$;

REVOKE ALL ON FUNCTION private_isg.record_drill_result(uuid,date,jsonb,text,text,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private_isg.record_appointment(p_company uuid,p_employee uuid,p_kind text,p_workplace uuid,
  p_starts_on date,p_ends_before date,p_asset uuid,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE appointment uuid;
BEGIN
  PERFORM private_isg.module_scope('appointment',p_company,p_workplace,true);
  IF p_employee IS NULL OR p_kind IS NULL OR p_starts_on IS NULL OR NOT isfinite(p_starts_on) OR p_now IS NULL OR
     p_kind NOT IN ('representative','support_staff','team_member','first_aid','fire_team') OR
     (p_ends_before IS NOT NULL AND p_ends_before<=p_starts_on) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  PERFORM 1 FROM private_isg.employees WHERE company_id=p_company AND id=p_employee AND NOT is_archived FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  IF p_asset IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='FILE_STORAGE_UNAVAILABLE'; END IF;
  BEGIN
    INSERT INTO private_isg.appointments(company_id,employee_id,kind,scope_workplace_id,starts_on,ends_before,asset_id,created_at,updated_at)
      VALUES(p_company,p_employee,p_kind,p_workplace,p_starts_on,p_ends_before,p_asset,p_now,p_now)
      RETURNING appointment_id INTO appointment;
  EXCEPTION WHEN exclusion_violation THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='APPOINTMENT_OVERLAP';
  END;
  RETURN jsonb_build_object('schema_version',1,'appointment_id',appointment,'kind',p_kind,'starts_on',p_starts_on,
    'ends_before',p_ends_before);
END $$;

REVOKE ALL ON FUNCTION private_isg.record_appointment(uuid,uuid,text,uuid,date,date,uuid,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private_isg.end_appointment(p_appointment uuid,p_ends_before date,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.appointments;
BEGIN
  PERFORM private_isg.module_gate('appointment',true);
  IF p_appointment IS NULL OR p_ends_before IS NULL OR NOT isfinite(p_ends_before) OR p_now IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT * INTO entry FROM private_isg.appointments WHERE appointment_id=p_appointment FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  IF entry.ends_before IS NOT NULL AND entry.ends_before=p_ends_before THEN
    RETURN jsonb_build_object('schema_version',1,'appointment_id',p_appointment,'ends_before',p_ends_before,'replayed',true); END IF;
  IF p_ends_before<=entry.starts_on THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  BEGIN
    UPDATE private_isg.appointments SET ends_before=p_ends_before,updated_at=p_now WHERE appointment_id=p_appointment;
  EXCEPTION WHEN exclusion_violation THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='APPOINTMENT_OVERLAP';
  END;
  RETURN jsonb_build_object('schema_version',1,'appointment_id',p_appointment,'ends_before',p_ends_before,'replayed',false);
END $$;

REVOKE ALL ON FUNCTION private_isg.end_appointment(uuid,date,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private_isg.record_ppe_handover(p_company uuid,p_employee uuid,p_item text,p_quantity numeric,
  p_unit text,p_handed_on date,p_asset uuid,p_signed boolean,p_external_ref text,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE handover uuid; existing uuid; reference text;
BEGIN
  PERFORM private_isg.module_gate('ppe',true);
  IF p_company IS NULL OR p_employee IS NULL OR p_item IS NULL OR p_quantity IS NULL OR p_quantity<=0 OR
     p_unit IS NULL OR p_unit NOT IN ('piece','pair','set','metre','litre') OR p_handed_on IS NULL OR
     NOT isfinite(p_handed_on) OR p_signed IS NULL OR p_now IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  PERFORM 1 FROM private_isg.employees WHERE company_id=p_company AND id=p_employee FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  -- A signed copy is a recorded document, never an assumption.
  IF p_signed AND p_asset IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='SIGNED_COPY_REQUIRED'; END IF;
  IF p_asset IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='FILE_STORAGE_UNAVAILABLE'; END IF;
  reference:=CASE WHEN p_external_ref IS NULL THEN NULL ELSE private_isg.text_value(p_external_ref,200) END;
  IF reference IS NOT NULL THEN
    SELECT handover_id INTO existing FROM private_isg.ppe_handovers
      WHERE company_id=p_company AND employee_id=p_employee AND external_ref=reference;
    IF FOUND THEN RETURN jsonb_build_object('schema_version',1,'handover_id',existing,'replayed',true); END IF;
  END IF;
  INSERT INTO private_isg.ppe_handovers(company_id,employee_id,item,quantity,unit,handed_on,evidence_asset_id,
      signed_copy,external_ref,created_at)
    VALUES(p_company,p_employee,private_isg.text_value(p_item,200),p_quantity,p_unit,p_handed_on,p_asset,p_signed,
      reference,p_now) RETURNING handover_id INTO handover;
  RETURN jsonb_build_object('schema_version',1,'handover_id',handover,'quantity',p_quantity,'signed_copy',p_signed,'replayed',false);
END $$;

REVOKE ALL ON FUNCTION private_isg.record_ppe_handover(uuid,uuid,text,numeric,text,date,uuid,boolean,text,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private_isg.record_ppe_return(p_handover uuid,p_quantity numeric,p_returned_on date,
  p_condition text,p_note text,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.ppe_handovers; returned numeric; record_id uuid;
BEGIN
  PERFORM private_isg.module_gate('ppe',true);
  IF p_handover IS NULL OR p_quantity IS NULL OR p_quantity<=0 OR p_returned_on IS NULL OR
     NOT isfinite(p_returned_on) OR p_condition IS NULL OR p_now IS NULL OR
     p_condition NOT IN ('reusable','worn','damaged','lost') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT * INTO entry FROM private_isg.ppe_handovers WHERE handover_id=p_handover FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  -- Nothing comes back before it was handed out.
  IF p_returned_on<entry.handed_on THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='RETURN_BEFORE_HANDOVER'; END IF;
  SELECT coalesce(sum(quantity),0) INTO returned FROM private_isg.ppe_returns WHERE handover_id=p_handover;
  IF returned+p_quantity>entry.quantity THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='RETURN_EXCEEDS_HANDOVER'; END IF;
  INSERT INTO private_isg.ppe_returns(handover_id,quantity,returned_on,condition,note,created_at)
    VALUES(p_handover,p_quantity,p_returned_on,p_condition,p_note,p_now) RETURNING return_id INTO record_id;
  RETURN jsonb_build_object('schema_version',1,'return_id',record_id,'returned_total',returned+p_quantity,
    'handed_quantity',entry.quantity,'outstanding',entry.quantity-(returned+p_quantity));
END $$;

REVOKE ALL ON FUNCTION private_isg.record_ppe_return(uuid,numeric,date,text,text,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

-- P10 client slice: the surface behind "Acil Durum Planları".
-- Additive. No rollout row is added and none is opened: this rides on the
-- `modules` feature and the `emergency_plan` module switch P10 already created.
--
-- The P10 core slice built the versioned plan whose renewal supersedes only the
-- pointer, so a previous version keeps its own scope, team snapshot, dates and
-- file. What it never had was a client boundary, and `publish_emergency_plan`
-- carried no ownership check: `module_scope` proves the workplace belongs to the
-- company, never that the company belongs to the caller.
--
-- Five things this slice makes structurally impossible:
--   1. Another owner's plan cannot be reached, and a renewal cannot be aimed at
--      a plan that is not this company's.
--   2. A renewal never rewrites what came before. The read returns every
--      version with its own team, dates and scope, so the history is visible
--      rather than asserted.
--   3. A validity date is never presented as a legal period. No approved
--      renewal catalogue exists, so the date is the expert's and the read says
--      so on every row. A plan with no date reads 'period_unknown', never
--      'valid'.
--   4. An unverified legal basis stays in review. `needs_review` is set by the
--      core function from the absence of a written basis; there is no payload
--      field that can clear it, and no action can edit a published version.
--   5. A team snapshot cannot be arbitrary JSON. Every entry is checked here
--      for a name and a role from a fixed set, so what is frozen into a plan is
--      a team rather than whatever the client happened to send.
SET LOCAL lock_timeout='5s';

CREATE TABLE private_isg.emergency_plan_receipts (
  actor_id uuid NOT NULL, mutation_id uuid NOT NULL, company_id uuid NOT NULL,
  operation_id uuid NOT NULL, request_hash bytea NOT NULL, response jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,mutation_id),
  FOREIGN KEY(company_id,actor_id) REFERENCES public.companies(id,user_id) ON DELETE CASCADE
);
CREATE INDEX emergency_plan_receipt_company_idx ON private_isg.emergency_plan_receipts(company_id,actor_id);
ALTER TABLE private_isg.emergency_plan_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA private_isg FROM PUBLIC,anon,authenticated,service_role;

-- How early the page starts warning that a plan runs out. The product's own
-- warning distance, reported on every read, never a legal period.
CREATE FUNCTION private_isg.emergency_notice_days() RETURNS integer
LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$ SELECT 30 $$;

-- The roles a team entry may carry. A fixed set in the schema, so a snapshot
-- cannot be filled with whatever the client invents.
CREATE TABLE private_isg.emergency_team_roles (
  role_code text PRIMARY KEY CHECK(role_code IN ('coordinator','fire','first_aid','evacuation','other')),
  ordinal integer NOT NULL CHECK(ordinal BETWEEN 1 AND 99),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(ordinal)
);
INSERT INTO private_isg.emergency_team_roles(role_code,ordinal) VALUES
  ('coordinator',1),('fire',2),('first_aid',3),('evacuation',4),('other',5);
ALTER TABLE private_isg.emergency_team_roles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA private_isg FROM PUBLIC,anon,authenticated,service_role;

-- What a plan says about itself today. Nothing is stored: the answer is worked
-- out from the active version's own dates at read time.
--
-- 'period_unknown' is the honest answer when a plan is published with no end
-- date. It is deliberately NOT 'valid': not knowing when a plan runs out is a
-- gap in the record, never a statement that it still stands.
CREATE FUNCTION private_isg.emergency_plan_status(p_valid_until date,p_has_version boolean,
  p_notice_days integer,p_today date) RETURNS text
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
BEGIN
  IF NOT p_has_version THEN RETURN 'never_published'; END IF;
  IF p_valid_until IS NULL THEN RETURN 'period_unknown'; END IF;
  IF p_valid_until<p_today THEN RETURN 'expired'; END IF;
  IF p_valid_until<=p_today+p_notice_days THEN RETURN 'due_soon'; END IF;
  RETURN 'valid';
END $$;

-- Four counters over five states, every state in exactly one group.
CREATE FUNCTION private_isg.emergency_plan_group(p_state text) RETURNS text
LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
  SELECT CASE p_state
    WHEN 'valid' THEN 'current'
    WHEN 'due_soon' THEN 'due_soon'
    WHEN 'expired' THEN 'expired'
    ELSE 'untracked' END
$$;

CREATE FUNCTION private_isg.emergency_plan_gate(p_write boolean) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
  PERFORM private_isg.module_gate('emergency_plan',p_write);
END $$;

-- A NULL company is the whole account, and only for reads: every write names
-- the company it writes into. `publish_emergency_plan` was written for a caller
-- that had already checked ownership; this is that caller.
CREATE FUNCTION private_isg.require_emergency_company(p_company uuid,p_write boolean) RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=private_isg.active_actor();
BEGIN
  IF NOT private_isg.p05_pilot_account_enabled(actor,p_write) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='FEATURE_UNAVAILABLE'; END IF;
  IF p_company IS NOT NULL AND NOT private_isg.p05_pilot_can_read(actor,p_company) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  PERFORM private_isg.emergency_plan_gate(p_write);
  IF p_write THEN
    IF p_company IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM public.user_subscriptions WHERE user_id=actor AND tier IN ('plus','pro') AND
      status IN ('active','trialing','grace_period') AND
      (current_period_ends_at IS NULL OR current_period_ends_at>clock_timestamp()) FOR SHARE;
    IF NOT FOUND OR private.user_plan_tier(actor) NOT IN ('plus','pro') THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAID_PLAN_REQUIRED'; END IF;
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor AND NOT is_archived FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSIF p_company IS NOT NULL THEN
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor) THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  END IF;
  RETURN actor;
END $$;

-- What may be frozen into a plan as its team. The core function only checks
-- that it is an array; this checks that every entry is a person with a role.
CREATE FUNCTION private_isg.emergency_team_snapshot(p_team jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE entry jsonb; cleaned jsonb:='[]'::jsonb; name text; role text; contact text; offending text;
BEGIN
  IF p_team IS NULL OR jsonb_typeof(p_team)<>'array' OR
     jsonb_array_length(p_team) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  FOR entry IN SELECT * FROM jsonb_array_elements(p_team) LOOP
    IF jsonb_typeof(entry)<>'object' THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    -- Only these three keys, so nothing else rides into the snapshot.
    SELECT key INTO offending FROM jsonb_object_keys(entry) AS keys(key)
      WHERE key NOT IN ('full_name','role','contact') ORDER BY key LIMIT 1;
    IF offending IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAYLOAD_NOT_ALLOWED'; END IF;
    name:=nullif(btrim(coalesce(entry->>'full_name','')),'');
    role:=nullif(btrim(coalesce(entry->>'role','')),'');
    contact:=nullif(btrim(coalesce(entry->>'contact','')),'');
    IF name IS NULL OR length(name)>200 OR role IS NULL OR
       (contact IS NOT NULL AND length(contact)>120) THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM private_isg.emergency_team_roles WHERE role_code=role;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='TEAM_ROLE_UNKNOWN'; END IF;
    cleaned:=cleaned||jsonb_build_array(jsonb_strip_nulls(
      jsonb_build_object('full_name',name,'role',role,'contact',contact)));
  END LOOP;
  RETURN cleaned;
END $$;

-- One plan: the version that stands today, and every version behind it with its
-- own team, dates and scope.
CREATE FUNCTION private_isg.emergency_plan_row(p_plan uuid,p_today date,p_history boolean) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE active private_isg.emergency_plan_versions;
  notice integer:=private_isg.emergency_notice_days(); shown_state text; total integer;
BEGIN
  SELECT * INTO active FROM private_isg.emergency_plan_versions
    WHERE plan_id=p_plan AND state='active';
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT count(*) INTO total FROM private_isg.emergency_plan_versions WHERE plan_id=p_plan;
  shown_state:=private_isg.emergency_plan_status(active.valid_until,true,notice,p_today);
  RETURN jsonb_build_object(
    'id',active.plan_id,'company_id',active.company_id,'workplace_id',active.workplace_id,
    'version',active.version,'versions_total',total,
    'scope',active.scope,'prepared_on',active.prepared_on,'valid_until',active.valid_until,
    'created_at',active.created_at,
    'state',shown_state,'state_group',private_isg.emergency_plan_group(shown_state),
    'state_authority','computed_at_read','notice_days',notice,
    -- The basis the expert wrote down, and the flag its absence forces.
    'needs_review',active.needs_review,'review_note',active.review_note,
    -- The date is the expert's: no approved renewal catalogue exists.
    'period_source','expert','period_needs_review',true,
    'team',active.team_snapshot,'team_size',jsonb_array_length(active.team_snapshot),
    'asset_id',active.asset_id,
    'versions',CASE WHEN p_history THEN
      (SELECT coalesce(jsonb_agg(jsonb_build_object('version',v.version,'state',v.state,
          'scope',v.scope,'prepared_on',v.prepared_on,'valid_until',v.valid_until,
          'needs_review',v.needs_review,'review_note',v.review_note,
          -- Each version keeps its own team. Renewing never rewrites an older one.
          'team',v.team_snapshot,'team_size',jsonb_array_length(v.team_snapshot),
          'asset_id',v.asset_id,'created_at',v.created_at)
          ORDER BY v.version DESC),'[]'::jsonb)
       FROM private_isg.emergency_plan_versions v WHERE v.plan_id=p_plan) END,
    'compliance_verdict',NULL,'health_records_tracked',false);
END $$;

CREATE FUNCTION private_isg.read_emergency_plans(p_company uuid,p_kind text,p_query text,p_state text,
  p_workplace uuid,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; needle text; today date; notice integer:=private_isg.emergency_notice_days();
  page_limit integer; page_offset integer;
  tally_all jsonb; tally_companies jsonb; tally_rows jsonb; matching_rows integer;
BEGIN
  actor:=private_isg.require_emergency_company(p_company,false);
  IF p_kind IS NULL OR p_kind NOT IN ('catalog','list','detail') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(clock_timestamp() AT TIME ZONE 'Europe/Istanbul')::date;

  IF p_kind='catalog' THEN
    RETURN jsonb_build_object('schema_version',1,'kind','catalog','notice_days',notice,
      'workplaces',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',w.id,'name',w.name,
          'needs_review',w.needs_review) ORDER BY w.name),'[]'::jsonb)
        FROM private_isg.workplaces w
        WHERE p_company IS NOT NULL AND w.company_id=p_company AND w.owner_id=actor AND NOT w.is_archived),
      'team_roles',(SELECT coalesce(jsonb_agg(jsonb_build_object('code',r.role_code,'ordinal',r.ordinal)
          ORDER BY r.ordinal),'[]'::jsonb) FROM private_isg.emergency_team_roles r),
      -- The product proposes no renewal period, because no approved catalogue
      -- exists. Whatever date the expert writes is stored as the expert's.
      'period_defaults_offered',false,
      'expert_period_source','expert',
      'review_cleared_by_note',true,
      'health_records_tracked',false);
  END IF;

  IF p_kind='detail' THEN
    IF p_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM private_isg.emergency_plan_versions v
      JOIN public.companies c ON c.id=v.company_id AND c.user_id=actor
      WHERE v.plan_id=p_id AND (p_company IS NULL OR v.company_id=p_company);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    RETURN jsonb_build_object('schema_version',1,'kind','detail','today',today,
      'row',private_isg.emergency_plan_row(p_id,today,true));
  END IF;

  IF p_state IS NOT NULL AND p_state NOT IN ('never_published','period_unknown','expired','due_soon','valid',
    'current','untracked') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  page_limit:=least(greatest(coalesce(p_limit,10),1),100);
  page_offset:=greatest(coalesce(p_offset,0),0);
  needle:=nullif(btrim(coalesce(p_query,'')),'');

  WITH scope AS (
    SELECT c.id,c.name FROM public.companies c WHERE c.user_id=actor AND NOT c.is_archived AND private_isg.p05_pilot_can_read(actor,c.id)
  ), page AS (
    SELECT v.plan_id,v.company_id,s.name AS company_name,v.workplace_id,w.name AS workplace_name,
      v.scope AS plan_scope,
      private_isg.emergency_plan_status(v.valid_until,true,notice,today) AS entry_state,
      v.valid_until,v.needs_review,
      -- Worst first: what ran out, then what has no end date, then what is due.
      row_number() OVER (ORDER BY
        CASE private_isg.emergency_plan_status(v.valid_until,true,notice,today)
          WHEN 'expired' THEN 0 WHEN 'period_unknown' THEN 1 WHEN 'due_soon' THEN 2 ELSE 3 END,
        v.valid_until NULLS FIRST,s.name,w.name,v.plan_id) AS ordinal
    FROM private_isg.emergency_plan_versions v
    JOIN scope s ON s.id=v.company_id
    JOIN private_isg.workplaces w ON w.company_id=v.company_id AND w.id=v.workplace_id
    WHERE v.owner_id=actor AND v.state='active' AND NOT w.is_archived
  ), scoped AS (
    SELECT * FROM page WHERE (p_company IS NULL OR company_id=p_company)
  ), filtered AS (
    SELECT * FROM scoped
    WHERE (p_workplace IS NULL OR workplace_id=p_workplace)
      AND (p_state IS NULL OR entry_state=p_state
        OR private_isg.emergency_plan_group(entry_state)=p_state)
      AND (needle IS NULL OR plan_scope ILIKE '%'||needle||'%'
           OR workplace_name ILIKE '%'||needle||'%' OR company_name ILIKE '%'||needle||'%')
  )
  SELECT
    (SELECT coalesce(jsonb_object_agg(state,total),'{}'::jsonb) FROM
      (SELECT entry_state AS state,count(*) AS total FROM page GROUP BY entry_state) a),
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'total',total,'counts',states)
       ORDER BY name),'[]'::jsonb) FROM
      (SELECT company_id AS id,max(company_name) AS name,count(*) AS total,
        jsonb_object_agg(entry_state,state_total) AS states FROM
        (SELECT company_id,company_name,entry_state,count(*) AS state_total FROM page
          GROUP BY company_id,company_name,entry_state) b GROUP BY company_id) c),
    (SELECT count(*) FROM filtered),
    (SELECT coalesce(jsonb_agg(entry ORDER BY sort),'[]'::jsonb) FROM (
       SELECT picked.ordinal AS sort,
         private_isg.emergency_plan_row(picked.plan_id,today,false)
           ||jsonb_build_object('company_name',picked.company_name,
               'workplace_name',picked.workplace_name) AS entry
       FROM (SELECT * FROM filtered ORDER BY ordinal LIMIT page_limit OFFSET page_offset) picked) built)
  INTO tally_all,tally_companies,matching_rows,tally_rows;

  RETURN jsonb_build_object('schema_version',1,'kind','list','rows',tally_rows,'today',today,
    'counts',tally_all,'companies',tally_companies,
    'total',matching_rows,'returned',jsonb_array_length(tally_rows),
    'has_more',page_offset+jsonb_array_length(tally_rows)<matching_rows,
    'limit',page_limit,'offset',page_offset,'notice_days',notice,
    'compliance_verdict',NULL,'health_records_tracked',false);
END $$;

-- Publishing is the only write. There is no edit: correcting a plan means
-- publishing the next version, and the one before it keeps everything it had.
CREATE FUNCTION private_isg.mutate_emergency_plans(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; allowed text[]; offending text; fingerprint bytea; prior private_isg.emergency_plan_receipts;
  result jsonb; answer jsonb; plan uuid; team jsonb;
  stamp timestamptz:=clock_timestamp(); today date;
BEGIN
  actor:=private_isg.require_emergency_company(p_company,true);
  IF p_action IS NULL OR p_operation IS NULL OR p_mutation IS NULL OR p_payload IS NULL OR
     jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>16384 THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(stamp AT TIME ZONE 'Europe/Istanbul')::date;
  allowed:=CASE p_action
    -- No `needs_review` here: the flag follows from whether a basis was
    -- written, and nothing may set it directly.
    WHEN 'publish_plan' THEN ARRAY['plan_id','workplace_id','scope','prepared_on','valid_until',
      'team','review_note']
    ELSE NULL END;
  IF allowed IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT key INTO offending FROM jsonb_object_keys(p_payload) AS keys(key)
    WHERE NOT (key=ANY(allowed)) ORDER BY key LIMIT 1;
  IF offending IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAYLOAD_NOT_ALLOWED'; END IF;

  fingerprint:=sha256(convert_to(jsonb_build_array(p_company,p_action,p_operation,p_payload)::text,'UTF8'));
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||':isg-emergency:'||p_mutation::text,0));
  SELECT * INTO prior FROM private_isg.emergency_plan_receipts WHERE actor_id=actor AND mutation_id=p_mutation;
  IF FOUND THEN
    IF prior.request_hash IS DISTINCT FROM fingerprint THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='IDEMPOTENCY_CONFLICT'; END IF;
    RETURN prior.response||jsonb_build_object('replayed',true);
  END IF;

  IF p_payload->>'workplace_id' IS NULL OR p_payload->>'scope' IS NULL OR
     p_payload->>'prepared_on' IS NULL OR NOT p_payload ? 'team' THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  PERFORM 1 FROM private_isg.workplaces WHERE company_id=p_company
    AND id=(p_payload->>'workplace_id')::uuid AND owner_id=actor AND NOT is_archived;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  -- A renewal must be aimed at a plan this company already holds.
  IF p_payload->>'plan_id' IS NOT NULL THEN
    plan:=(p_payload->>'plan_id')::uuid;
    PERFORM 1 FROM private_isg.emergency_plan_versions
      WHERE plan_id=plan AND company_id=p_company AND owner_id=actor FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  END IF;
  -- A prepared date in the future would be a plan that does not exist yet.
  IF (p_payload->>'prepared_on')::date>today THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PREPARED_IN_THE_FUTURE'; END IF;
  team:=private_isg.emergency_team_snapshot(p_payload->'team');
  answer:=private_isg.publish_emergency_plan(p_company,(p_payload->>'workplace_id')::uuid,plan,
    p_payload->>'scope',(p_payload->>'prepared_on')::date,(p_payload->>'valid_until')::date,
    team,NULL,nullif(btrim(coalesce(p_payload->>'review_note','')),''),stamp);
  plan:=(answer->>'plan_id')::uuid;

  result:=jsonb_build_object('schema_version',1,'action',p_action,'plan_id',plan,'answer',answer,
    'row',private_isg.emergency_plan_row(plan,today,true));
  INSERT INTO private_isg.emergency_plan_receipts(actor_id,mutation_id,company_id,operation_id,request_hash,response)
    VALUES(actor,p_mutation,p_company,p_operation,fingerprint,result);
  RETURN result||jsonb_build_object('replayed',false);
END $$;

CREATE FUNCTION public.isg_emergency_plans_read_v1(p_company uuid,p_kind text,p_query text,p_state text,
  p_workplace uuid,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.read_emergency_plans(p_company,p_kind,p_query,p_state,p_workplace,p_id,p_limit,p_offset)
$$;
CREATE FUNCTION public.isg_emergency_plans_mutate_v1(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.mutate_emergency_plans(p_company,p_action,p_operation,p_mutation,p_payload)
$$;

REVOKE ALL ON FUNCTION private_isg.emergency_notice_days(),
  private_isg.emergency_plan_status(date,boolean,integer,date),
  private_isg.emergency_plan_group(text),
  private_isg.emergency_plan_gate(boolean),
  private_isg.require_emergency_company(uuid,boolean),
  private_isg.emergency_team_snapshot(jsonb),
  private_isg.emergency_plan_row(uuid,date,boolean),
  private_isg.read_emergency_plans(uuid,text,text,text,uuid,uuid,integer,integer),
  private_isg.mutate_emergency_plans(uuid,text,uuid,uuid,jsonb),
  public.isg_emergency_plans_read_v1(uuid,text,text,text,uuid,uuid,integer,integer),
  public.isg_emergency_plans_mutate_v1(uuid,text,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION private_isg.read_emergency_plans(uuid,text,text,text,uuid,uuid,integer,integer),
  private_isg.mutate_emergency_plans(uuid,text,uuid,uuid,jsonb),
  public.isg_emergency_plans_read_v1(uuid,text,text,text,uuid,uuid,integer,integer),
  public.isg_emergency_plans_mutate_v1(uuid,text,uuid,uuid,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';


-- P10 client slice: the surface behind "Tatbikatlar".
-- Additive. No rollout row is added and none is opened: this rides on the
-- `modules` feature and the `drill` module switch P10 already created.
--
-- The P10 core built the drill record and kept planning apart from performing.
-- Three things were missing rather than merely unreachable:
--
--   1. No client boundary, and `plan_drill` / `record_drill_result` carried no
--      ownership check — `module_scope` proves the workplace belongs to the
--      company, never that the company belongs to the caller, and recording a
--      result took a drill id and trusted it.
--   2. Nothing could cancel a drill. The state and its mandatory reason were in
--      the schema with no function to write them.
--   3. Participants were stored as employee ids alone. Renaming or archiving a
--      person later would have changed what a performed drill said about who
--      was there.
--
-- Five things this slice makes structurally impossible:
--   1. Another owner's drill or plan cannot be reached, and a drill cannot
--      rehearse a plan belonging to a different workplace.
--   2. Planning is not performing. A planned date that has passed reads
--      'overdue', never 'performed', and every read reports `performed` from
--      the record rather than from a date.
--   3. A performed drill is closed: no second result, and no cancellation
--      after the fact.
--   4. Who took part is frozen at the moment it is recorded. Changing the
--      personnel register afterwards never edits a performed drill.
--   5. A drill is pinned to the plan version it rehearsed. The client cannot
--      name a version at all: the boundary resolves the one in force, and
--      publishing a newer plan later never re-points it.
SET LOCAL lock_timeout='5s';

-- Who was there, as they were named at the time. The core stores ids; this
-- keeps the answer a performed drill gave when it was given.
ALTER TABLE private_isg.drill_records
  ADD COLUMN participant_snapshot jsonb,
  ADD CONSTRAINT drill_snapshot_shape_check
    CHECK(participant_snapshot IS NULL OR jsonb_typeof(participant_snapshot)='array');

CREATE TABLE private_isg.drill_receipts (
  actor_id uuid NOT NULL, mutation_id uuid NOT NULL, company_id uuid NOT NULL,
  operation_id uuid NOT NULL, request_hash bytea NOT NULL, response jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,mutation_id),
  FOREIGN KEY(company_id,actor_id) REFERENCES public.companies(id,user_id) ON DELETE CASCADE
);
CREATE INDEX drill_receipt_company_idx ON private_isg.drill_receipts(company_id,actor_id);
ALTER TABLE private_isg.drill_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA private_isg FROM PUBLIC,anon,authenticated,service_role;

-- How early the page starts warning that a planned drill is coming up. The
-- product's own warning distance, reported on every read.
CREATE FUNCTION private_isg.drill_notice_days() RETURNS integer
LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$ SELECT 14 $$;

-- What a drill says about itself today. Nothing is stored beyond the record's
-- own state; overdue and due soon are worked out from the planned date.
--
-- A planned date that has passed reads 'overdue'. It is deliberately never
-- 'performed': a date going by is not a drill being held.
CREATE FUNCTION private_isg.drill_status(p_state text,p_planned_on date,p_notice_days integer,
  p_today date) RETURNS text
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
BEGIN
  IF p_state='performed' THEN RETURN 'performed'; END IF;
  IF p_state='cancelled' THEN RETURN 'cancelled'; END IF;
  IF p_planned_on<p_today THEN RETURN 'overdue'; END IF;
  IF p_planned_on<=p_today+p_notice_days THEN RETURN 'due_soon'; END IF;
  RETURN 'scheduled';
END $$;

-- Four counters over five states, every state in exactly one group.
CREATE FUNCTION private_isg.drill_group(p_state text) RETURNS text
LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
  SELECT CASE p_state
    WHEN 'overdue' THEN 'overdue'
    WHEN 'due_soon' THEN 'due_soon'
    WHEN 'scheduled' THEN 'scheduled'
    ELSE 'closed' END
$$;

CREATE FUNCTION private_isg.drill_gate(p_write boolean) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
  PERFORM private_isg.module_gate('drill',p_write);
END $$;

CREATE FUNCTION private_isg.require_drill_company(p_company uuid,p_write boolean) RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=private_isg.active_actor();
BEGIN
  IF NOT private_isg.p05_pilot_account_enabled(actor,p_write) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='FEATURE_UNAVAILABLE'; END IF;
  IF p_company IS NOT NULL AND NOT private_isg.p05_pilot_can_read(actor,p_company) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  PERFORM private_isg.drill_gate(p_write);
  IF p_write THEN
    IF p_company IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM public.user_subscriptions WHERE user_id=actor AND tier IN ('plus','pro') AND
      status IN ('active','trialing','grace_period') AND
      (current_period_ends_at IS NULL OR current_period_ends_at>clock_timestamp()) FOR SHARE;
    IF NOT FOUND OR private.user_plan_tier(actor) NOT IN ('plus','pro') THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAID_PLAN_REQUIRED'; END IF;
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor AND NOT is_archived FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSIF p_company IS NOT NULL THEN
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor) THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  END IF;
  RETURN actor;
END $$;

-- The missing state transition. A drill that was held is a record of what
-- happened; it is not withdrawn.
CREATE FUNCTION private_isg.cancel_drill(p_drill uuid,p_reason text,p_now timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.drill_records;
BEGIN
  PERFORM private_isg.module_gate('drill',true);
  IF p_drill IS NULL OR p_now IS NULL OR p_reason IS NULL OR btrim(p_reason)='' THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT * INTO entry FROM private_isg.drill_records WHERE drill_id=p_drill FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  IF entry.state='cancelled' THEN
    RETURN jsonb_build_object('schema_version',1,'drill_id',p_drill,'state','cancelled','replayed',true); END IF;
  IF entry.state<>'planned' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='DRILL_PERFORMED'; END IF;
  UPDATE private_isg.drill_records SET state='cancelled',
    cancelled_reason=private_isg.text_value(p_reason,500),updated_at=p_now WHERE drill_id=p_drill;
  RETURN jsonb_build_object('schema_version',1,'drill_id',p_drill,'state','cancelled','replayed',false);
END $$;

-- One drill: what it rehearsed, when, and who was there as they were named at
-- the time.
CREATE FUNCTION private_isg.drill_row(p_drill uuid,p_today date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.drill_records; plan private_isg.emergency_plan_versions;
  notice integer:=private_isg.drill_notice_days(); shown_state text;
BEGIN
  SELECT * INTO entry FROM private_isg.drill_records WHERE drill_id=p_drill;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO plan FROM private_isg.emergency_plan_versions
    WHERE plan_id=entry.plan_id AND version=entry.plan_version;
  shown_state:=private_isg.drill_status(entry.state,entry.planned_on,notice,p_today);
  RETURN jsonb_build_object(
    'id',entry.drill_id,'company_id',entry.company_id,'workplace_id',entry.workplace_id,
    'plan_id',entry.plan_id,'plan_version',entry.plan_version,'plan_scope',plan.scope,
    -- Whether the plan has moved on since. The drill still rehearsed the
    -- version it names, and is never re-pointed.
    'plan_version_superseded',plan.state<>'active',
    'planned_on',entry.planned_on,'performed_on',entry.performed_on,
    'state',shown_state,'record_state',entry.state,
    'state_group',private_isg.drill_group(shown_state),
    'state_authority','computed_at_read','notice_days',notice,
    -- Read from the record, never inferred from a date going by.
    'performed',entry.state='performed',
    'observation',entry.observation,'improvement',entry.improvement,
    'cancelled_reason',entry.cancelled_reason,
    'participants',coalesce(entry.participant_snapshot,'[]'::jsonb),
    'participant_count',coalesce(jsonb_array_length(entry.participant_snapshot),0),
    -- The names are the ones recorded at the time, not the register's today.
    'participants_snapshotted',entry.participant_snapshot IS NOT NULL,
    'created_at',entry.created_at,
    'compliance_verdict',NULL,'health_records_tracked',false);
END $$;

CREATE FUNCTION private_isg.read_drills(p_company uuid,p_kind text,p_query text,p_state text,
  p_workplace uuid,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; needle text; today date; notice integer:=private_isg.drill_notice_days();
  page_limit integer; page_offset integer;
  tally_all jsonb; tally_companies jsonb; tally_rows jsonb; matching_rows integer;
BEGIN
  actor:=private_isg.require_drill_company(p_company,false);
  IF p_kind IS NULL OR p_kind NOT IN ('catalog','list','detail') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(clock_timestamp() AT TIME ZONE 'Europe/Istanbul')::date;

  IF p_kind='catalog' THEN
    RETURN jsonb_build_object('schema_version',1,'kind','catalog','notice_days',notice,
      -- Only plans that are in force can be rehearsed, and only this actor's.
      -- A drill without a plan is not offered, because the record has nowhere
      -- to point.
      'plans',(SELECT coalesce(jsonb_agg(jsonb_build_object('plan_id',v.plan_id,'version',v.version,
          'scope',v.scope,'workplace_id',v.workplace_id,'workplace_name',w.name,
          'valid_until',v.valid_until) ORDER BY w.name,v.scope),'[]'::jsonb)
        FROM private_isg.emergency_plan_versions v
        JOIN private_isg.workplaces w ON w.company_id=v.company_id AND w.id=v.workplace_id
        WHERE p_company IS NOT NULL AND v.company_id=p_company AND v.owner_id=actor
          AND v.state='active' AND NOT w.is_archived),
      'employees',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'full_name',e.full_name)
          ORDER BY e.full_name),'[]'::jsonb)
        FROM private_isg.employees e
        WHERE p_company IS NOT NULL AND e.company_id=p_company AND NOT e.is_archived),
      -- The product proposes no drill period: no approved catalogue exists.
      'period_defaults_offered',false,
      'participants_are_snapshotted',true,
      'health_records_tracked',false);
  END IF;

  IF p_kind='detail' THEN
    IF p_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM private_isg.drill_records d
      JOIN public.companies c ON c.id=d.company_id AND c.user_id=actor
      WHERE d.drill_id=p_id AND (p_company IS NULL OR d.company_id=p_company);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    RETURN jsonb_build_object('schema_version',1,'kind','detail','today',today,
      'row',private_isg.drill_row(p_id,today));
  END IF;

  IF p_state IS NOT NULL AND p_state NOT IN ('overdue','due_soon','scheduled','performed','cancelled',
    'closed') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  page_limit:=least(greatest(coalesce(p_limit,10),1),100);
  page_offset:=greatest(coalesce(p_offset,0),0);
  needle:=nullif(btrim(coalesce(p_query,'')),'');

  WITH scope AS (
    SELECT c.id,c.name FROM public.companies c WHERE c.user_id=actor AND NOT c.is_archived AND private_isg.p05_pilot_can_read(actor,c.id)
  ), page AS (
    SELECT d.drill_id,d.company_id,s.name AS company_name,d.workplace_id,w.name AS workplace_name,
      v.scope AS plan_scope,
      private_isg.drill_status(d.state,d.planned_on,notice,today) AS entry_state,
      d.planned_on,
      -- Worst first: what was missed, then what is coming up.
      row_number() OVER (ORDER BY
        CASE private_isg.drill_status(d.state,d.planned_on,notice,today)
          WHEN 'overdue' THEN 0 WHEN 'due_soon' THEN 1 WHEN 'scheduled' THEN 2 ELSE 3 END,
        d.planned_on,s.name,w.name,d.drill_id) AS ordinal
    FROM private_isg.drill_records d
    JOIN scope s ON s.id=d.company_id
    JOIN private_isg.workplaces w ON w.company_id=d.company_id AND w.id=d.workplace_id
    JOIN private_isg.emergency_plan_versions v
      ON v.plan_id=d.plan_id AND v.version=d.plan_version
    WHERE v.owner_id=actor AND NOT w.is_archived
  ), scoped AS (
    SELECT * FROM page WHERE (p_company IS NULL OR company_id=p_company)
  ), filtered AS (
    SELECT * FROM scoped
    WHERE (p_workplace IS NULL OR workplace_id=p_workplace)
      AND (p_state IS NULL OR entry_state=p_state
        OR private_isg.drill_group(entry_state)=p_state)
      AND (needle IS NULL OR plan_scope ILIKE '%'||needle||'%'
           OR workplace_name ILIKE '%'||needle||'%' OR company_name ILIKE '%'||needle||'%')
  )
  SELECT
    (SELECT coalesce(jsonb_object_agg(state,total),'{}'::jsonb) FROM
      (SELECT entry_state AS state,count(*) AS total FROM page GROUP BY entry_state) a),
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'total',total,'counts',states)
       ORDER BY name),'[]'::jsonb) FROM
      (SELECT company_id AS id,max(company_name) AS name,count(*) AS total,
        jsonb_object_agg(entry_state,state_total) AS states FROM
        (SELECT company_id,company_name,entry_state,count(*) AS state_total FROM page
          GROUP BY company_id,company_name,entry_state) b GROUP BY company_id) c),
    (SELECT count(*) FROM filtered),
    (SELECT coalesce(jsonb_agg(entry ORDER BY sort),'[]'::jsonb) FROM (
       SELECT picked.ordinal AS sort,
         private_isg.drill_row(picked.drill_id,today)
           ||jsonb_build_object('company_name',picked.company_name,
               'workplace_name',picked.workplace_name) AS entry
       FROM (SELECT * FROM filtered ORDER BY ordinal LIMIT page_limit OFFSET page_offset) picked) built)
  INTO tally_all,tally_companies,matching_rows,tally_rows;

  RETURN jsonb_build_object('schema_version',1,'kind','list','rows',tally_rows,'today',today,
    'counts',tally_all,'companies',tally_companies,
    'total',matching_rows,'returned',jsonb_array_length(tally_rows),
    'has_more',page_offset+jsonb_array_length(tally_rows)<matching_rows,
    'limit',page_limit,'offset',page_offset,'notice_days',notice,
    -- A tally of drills, never a statement that a workplace is prepared.
    'compliance_verdict',NULL,'health_records_tracked',false);
END $$;

CREATE FUNCTION private_isg.mutate_drills(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; allowed text[]; offending text; fingerprint bytea; prior private_isg.drill_receipts;
  result jsonb; answer jsonb; drill uuid; entry private_isg.drill_records;
  plan private_isg.emergency_plan_versions; snapshot jsonb;
  stamp timestamptz:=clock_timestamp(); today date;
BEGIN
  actor:=private_isg.require_drill_company(p_company,true);
  IF p_action IS NULL OR p_operation IS NULL OR p_mutation IS NULL OR p_payload IS NULL OR
     jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>16384 THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(stamp AT TIME ZONE 'Europe/Istanbul')::date;
  allowed:=CASE p_action
    -- No plan_version: the boundary pins the version in force, so a drill can
    -- never be aimed at a version the expert did not see.
    WHEN 'plan_drill' THEN ARRAY['plan_id','planned_on']
    WHEN 'record_result' THEN ARRAY['drill_id','performed_on','participants','observation','improvement']
    WHEN 'cancel_drill' THEN ARRAY['drill_id','reason']
    ELSE NULL END;
  IF allowed IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT key INTO offending FROM jsonb_object_keys(p_payload) AS keys(key)
    WHERE NOT (key=ANY(allowed)) ORDER BY key LIMIT 1;
  IF offending IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAYLOAD_NOT_ALLOWED'; END IF;

  fingerprint:=sha256(convert_to(jsonb_build_array(p_company,p_action,p_operation,p_payload)::text,'UTF8'));
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||':isg-drill:'||p_mutation::text,0));
  SELECT * INTO prior FROM private_isg.drill_receipts WHERE actor_id=actor AND mutation_id=p_mutation;
  IF FOUND THEN
    IF prior.request_hash IS DISTINCT FROM fingerprint THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='IDEMPOTENCY_CONFLICT'; END IF;
    RETURN prior.response||jsonb_build_object('replayed',true);
  END IF;

  IF p_action='plan_drill' THEN
    IF p_payload->>'plan_id' IS NULL OR p_payload->>'planned_on' IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    -- The plan must be this actor's, in force, and its workplace is the
    -- drill's: a drill cannot rehearse another workplace's plan.
    SELECT * INTO plan FROM private_isg.emergency_plan_versions
      WHERE plan_id=(p_payload->>'plan_id')::uuid AND company_id=p_company
        AND owner_id=actor AND state='active' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    answer:=private_isg.plan_drill(p_company,plan.workplace_id,plan.plan_id,plan.version,
      (p_payload->>'planned_on')::date,stamp);
    drill:=(answer->>'drill_id')::uuid;
  ELSE
    drill:=(p_payload->>'drill_id')::uuid;
    SELECT * INTO entry FROM private_isg.drill_records
      WHERE drill_id=drill AND company_id=p_company FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    -- The company is the caller's, but the plan behind the drill must be too.
    PERFORM 1 FROM private_isg.emergency_plan_versions
      WHERE plan_id=entry.plan_id AND version=entry.plan_version AND owner_id=actor;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;

    IF p_action='record_result' THEN
      IF p_payload->>'performed_on' IS NULL OR NOT p_payload ? 'participants' THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
      -- A drill held tomorrow has not been held.
      IF (p_payload->>'performed_on')::date>today THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PERFORMED_IN_THE_FUTURE'; END IF;
      answer:=private_isg.record_drill_result(drill,(p_payload->>'performed_on')::date,
        p_payload->'participants',
        nullif(btrim(coalesce(p_payload->>'observation','')),''),
        nullif(btrim(coalesce(p_payload->>'improvement','')),''),stamp);
      -- Freeze who that was, as they are named now. The register may change
      -- afterwards; this record does not.
      IF NOT coalesce((answer->>'replayed')::boolean,false) THEN
        SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'full_name',e.full_name)
            ORDER BY e.full_name),'[]'::jsonb) INTO snapshot
          FROM private_isg.employees e
          WHERE e.company_id=p_company
            AND e.id::text IN (SELECT value FROM jsonb_array_elements_text(p_payload->'participants') AS t(value));
        UPDATE private_isg.drill_records SET participant_snapshot=snapshot WHERE drill_id=drill;
      END IF;
    ELSE
      IF p_payload->>'reason' IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
      answer:=private_isg.cancel_drill(drill,p_payload->>'reason',stamp);
    END IF;
  END IF;

  result:=jsonb_build_object('schema_version',1,'action',p_action,'drill_id',drill,'answer',answer,
    'row',private_isg.drill_row(drill,today));
  INSERT INTO private_isg.drill_receipts(actor_id,mutation_id,company_id,operation_id,request_hash,response)
    VALUES(actor,p_mutation,p_company,p_operation,fingerprint,result);
  RETURN result||jsonb_build_object('replayed',false);
END $$;

CREATE FUNCTION public.isg_drills_read_v1(p_company uuid,p_kind text,p_query text,p_state text,
  p_workplace uuid,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.read_drills(p_company,p_kind,p_query,p_state,p_workplace,p_id,p_limit,p_offset)
$$;
CREATE FUNCTION public.isg_drills_mutate_v1(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.mutate_drills(p_company,p_action,p_operation,p_mutation,p_payload)
$$;

REVOKE ALL ON FUNCTION private_isg.drill_notice_days(),
  private_isg.drill_status(text,date,integer,date),
  private_isg.drill_group(text),
  private_isg.drill_gate(boolean),
  private_isg.require_drill_company(uuid,boolean),
  private_isg.cancel_drill(uuid,text,timestamptz),
  private_isg.drill_row(uuid,date),
  private_isg.read_drills(uuid,text,text,text,uuid,uuid,integer,integer),
  private_isg.mutate_drills(uuid,text,uuid,uuid,jsonb),
  public.isg_drills_read_v1(uuid,text,text,text,uuid,uuid,integer,integer),
  public.isg_drills_mutate_v1(uuid,text,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION private_isg.read_drills(uuid,text,text,text,uuid,uuid,integer,integer),
  private_isg.mutate_drills(uuid,text,uuid,uuid,jsonb),
  public.isg_drills_read_v1(uuid,text,text,text,uuid,uuid,integer,integer),
  public.isg_drills_mutate_v1(uuid,text,uuid,uuid,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';


-- P10 client slice: the surface behind "KKD Zimmetleri".
-- Additive. No rollout row is added and none is opened: this rides on the
-- `modules` feature and the `ppe` module switch P10 already created.
--
-- The P10 core built the handover, the return and the two rules that matter:
-- nothing comes back before it went out, and no more comes back than went out.
-- Three things were missing rather than merely unreachable:
--
--   1. No client boundary, and no ownership check. `record_ppe_handover`
--      proves the employee belongs to the company, never that the company
--      belongs to the caller; `record_ppe_return` took a handover id and
--      trusted it entirely.
--   2. Nothing could take back a mistaken return. A return entered by accident
--      would misreport what a person is still holding, for good.
--   3. `signed_copy` demands a stored file, and there is no client path to
--      one, so the flag could only ever have been refused. What an expert
--      actually has is a signed form in a folder somewhere, and there was
--      nowhere to say where.
--
-- Five things this slice makes structurally impossible:
--   1. Another owner's handover or employee cannot be reached, and a return
--      cannot be filed against a handover outside the caller's company.
--   2. More cannot come back than went out, and nothing comes back before it
--      went out. Both rules stay in the core function; the boundary only
--      reaches it after proving who is asking.
--   3. The product never claims to hold a signed form. `signed_copy` is on no
--      allowlist, so it can only ever be false, and every read says the file
--      is not stored here — what is kept is the expert's own note of where it
--      is.
--   4. What a person is still holding is counted at read time from the returns
--      themselves, never stored. Removing a mistaken return corrects it at
--      once, with no field to fix by hand.
--   5. A handover dated tomorrow is refused: nothing was handed over on a day
--      that has not happened.
SET LOCAL lock_timeout='5s';

-- Where the signed form is kept. The tracker holds a reference, never the
-- file, exactly as the document tracker does.
ALTER TABLE private_isg.ppe_handovers
  ADD COLUMN signed_copy_location text
    CHECK(signed_copy_location IS NULL OR length(signed_copy_location)<=300);

CREATE TABLE private_isg.ppe_receipts (
  actor_id uuid NOT NULL, mutation_id uuid NOT NULL, company_id uuid NOT NULL,
  operation_id uuid NOT NULL, request_hash bytea NOT NULL, response jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,mutation_id),
  FOREIGN KEY(company_id,actor_id) REFERENCES public.companies(id,user_id) ON DELETE CASCADE
);
CREATE INDEX ppe_receipt_company_idx ON private_isg.ppe_receipts(company_id,actor_id);
ALTER TABLE private_isg.ppe_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA private_isg FROM PUBLIC,anon,authenticated,service_role;

-- What a handover says about itself. Three states, and each is its own
-- counter: there is no group layer here because nothing would be grouped.
CREATE FUNCTION private_isg.ppe_handover_status(p_handed numeric,p_returned numeric) RETURNS text
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
BEGIN
  IF coalesce(p_returned,0)<=0 THEN RETURN 'outstanding'; END IF;
  IF p_returned>=p_handed THEN RETURN 'closed'; END IF;
  RETURN 'partial';
END $$;

CREATE FUNCTION private_isg.ppe_gate(p_write boolean) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
  PERFORM private_isg.module_gate('ppe',p_write);
END $$;

CREATE FUNCTION private_isg.require_ppe_company(p_company uuid,p_write boolean) RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=private_isg.active_actor();
BEGIN
  IF NOT private_isg.p05_pilot_account_enabled(actor,p_write) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='FEATURE_UNAVAILABLE'; END IF;
  IF p_company IS NOT NULL AND NOT private_isg.p05_pilot_can_read(actor,p_company) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  PERFORM private_isg.ppe_gate(p_write);
  IF p_write THEN
    IF p_company IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM public.user_subscriptions WHERE user_id=actor AND tier IN ('plus','pro') AND
      status IN ('active','trialing','grace_period') AND
      (current_period_ends_at IS NULL OR current_period_ends_at>clock_timestamp()) FOR SHARE;
    IF NOT FOUND OR private.user_plan_tier(actor) NOT IN ('plus','pro') THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAID_PLAN_REQUIRED'; END IF;
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor AND NOT is_archived FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSIF p_company IS NOT NULL THEN
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor) THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  END IF;
  RETURN actor;
END $$;

-- The missing correction. A return entered by mistake is taken back; what the
-- person is still holding is recounted at the next read, because it was never
-- stored in the first place.
CREATE FUNCTION private_isg.remove_ppe_return(p_handover uuid,p_return uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.ppe_handovers; removed integer; returned numeric;
BEGIN
  PERFORM private_isg.module_gate('ppe',true);
  IF p_handover IS NULL OR p_return IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT * INTO entry FROM private_isg.ppe_handovers WHERE handover_id=p_handover FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  DELETE FROM private_isg.ppe_returns WHERE return_id=p_return AND handover_id=p_handover;
  GET DIAGNOSTICS removed=ROW_COUNT;
  IF removed=0 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  SELECT coalesce(sum(quantity),0) INTO returned FROM private_isg.ppe_returns WHERE handover_id=p_handover;
  RETURN jsonb_build_object('schema_version',1,'handover_id',p_handover,'return_id',p_return,
    'returned_total',returned,'handed_quantity',entry.quantity,'outstanding',entry.quantity-returned);
END $$;

-- One handover with what came back against it. Nothing is stored: the
-- outstanding amount is counted from the returns at read time.
CREATE FUNCTION private_isg.ppe_handover_row(p_handover uuid,p_history boolean) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.ppe_handovers; person private_isg.employees;
  returned numeric; lost numeric; shown_state text;
BEGIN
  SELECT * INTO entry FROM private_isg.ppe_handovers WHERE handover_id=p_handover;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO person FROM private_isg.employees
    WHERE company_id=entry.company_id AND id=entry.employee_id;
  SELECT coalesce(sum(quantity),0),coalesce(sum(quantity) FILTER (WHERE condition='lost'),0)
    INTO returned,lost FROM private_isg.ppe_returns WHERE handover_id=p_handover;
  shown_state:=private_isg.ppe_handover_status(entry.quantity,returned);
  RETURN jsonb_build_object(
    'id',entry.handover_id,'company_id',entry.company_id,'employee_id',entry.employee_id,
    'employee_name',person.full_name,'employee_archived',coalesce(person.is_archived,false),
    'item',entry.item,'quantity',entry.quantity,'unit',entry.unit,'handed_on',entry.handed_on,
    'external_ref',entry.external_ref,'created_at',entry.created_at,
    'state',shown_state,'state_authority','computed_at_read',
    'returned_quantity',returned,'outstanding',entry.quantity-returned,'lost_quantity',lost,
    -- The product holds no file, so this can only ever be false. What is kept
    -- is the expert's own note of where the signed form is.
    'signed_copy',entry.signed_copy,'signed_copy_stored',false,
    'signed_copy_location',entry.signed_copy_location,
    'returns',CASE WHEN p_history THEN
      (SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.return_id,'quantity',r.quantity,
          'returned_on',r.returned_on,'condition',r.condition,'note',r.note,'created_at',r.created_at)
          ORDER BY r.returned_on DESC,r.created_at DESC),'[]'::jsonb)
       FROM private_isg.ppe_returns r WHERE r.handover_id=p_handover) END,
    'compliance_verdict',NULL,'health_records_tracked',false);
END $$;

CREATE FUNCTION private_isg.read_ppe_handovers(p_company uuid,p_kind text,p_query text,p_state text,
  p_employee uuid,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; needle text; today date;
  page_limit integer; page_offset integer;
  tally_all jsonb; tally_companies jsonb; tally_rows jsonb; matching_rows integer;
BEGIN
  actor:=private_isg.require_ppe_company(p_company,false);
  IF p_kind IS NULL OR p_kind NOT IN ('catalog','list','detail') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(clock_timestamp() AT TIME ZONE 'Europe/Istanbul')::date;

  IF p_kind='catalog' THEN
    RETURN jsonb_build_object('schema_version',1,'kind','catalog',
      'employees',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'full_name',e.full_name)
          ORDER BY e.full_name),'[]'::jsonb)
        FROM private_isg.employees e
        WHERE p_company IS NOT NULL AND e.company_id=p_company AND NOT e.is_archived),
      'units',jsonb_build_array('piece','pair','set','metre','litre'),
      'conditions',jsonb_build_array('reusable','worn','damaged','lost'),
      -- No equipment catalogue ships: naming a fixed list of protective
      -- equipment would read as a statement of what the law requires, and no
      -- such list has been approved. The expert names the item.
      'item_catalogue_offered',false,
      -- The product holds no signed form, on any handover.
      'signed_copy_storage_available',false,
      'health_records_tracked',false);
  END IF;

  IF p_kind='detail' THEN
    IF p_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM private_isg.ppe_handovers h
      JOIN public.companies c ON c.id=h.company_id AND c.user_id=actor
      WHERE h.handover_id=p_id AND (p_company IS NULL OR h.company_id=p_company);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    RETURN jsonb_build_object('schema_version',1,'kind','detail','today',today,
      'row',private_isg.ppe_handover_row(p_id,true));
  END IF;

  IF p_state IS NOT NULL AND p_state NOT IN ('outstanding','partial','closed') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  page_limit:=least(greatest(coalesce(p_limit,10),1),100);
  page_offset:=greatest(coalesce(p_offset,0),0);
  needle:=nullif(btrim(coalesce(p_query,'')),'');

  WITH scope AS (
    SELECT c.id,c.name FROM public.companies c WHERE c.user_id=actor AND NOT c.is_archived AND private_isg.p05_pilot_can_read(actor,c.id)
  ), page AS (
    SELECT h.handover_id,h.company_id,s.name AS company_name,h.employee_id,e.full_name AS employee_name,
      h.item,h.handed_on,
      private_isg.ppe_handover_status(h.quantity,
        (SELECT coalesce(sum(r.quantity),0) FROM private_isg.ppe_returns r
          WHERE r.handover_id=h.handover_id)) AS entry_state,
      -- What is still out first: that is the question the page answers.
      row_number() OVER (ORDER BY
        CASE private_isg.ppe_handover_status(h.quantity,
          (SELECT coalesce(sum(r.quantity),0) FROM private_isg.ppe_returns r
            WHERE r.handover_id=h.handover_id))
          WHEN 'outstanding' THEN 0 WHEN 'partial' THEN 1 ELSE 2 END,
        h.handed_on DESC,s.name,e.full_name,h.handover_id) AS ordinal
    FROM private_isg.ppe_handovers h
    JOIN scope s ON s.id=h.company_id
    JOIN private_isg.employees e ON e.company_id=h.company_id AND e.id=h.employee_id
  ), scoped AS (
    SELECT * FROM page WHERE (p_company IS NULL OR company_id=p_company)
  ), filtered AS (
    SELECT * FROM scoped
    WHERE (p_employee IS NULL OR employee_id=p_employee)
      AND (p_state IS NULL OR entry_state=p_state)
      AND (needle IS NULL OR item ILIKE '%'||needle||'%'
           OR employee_name ILIKE '%'||needle||'%' OR company_name ILIKE '%'||needle||'%')
  )
  SELECT
    (SELECT coalesce(jsonb_object_agg(state,total),'{}'::jsonb) FROM
      (SELECT entry_state AS state,count(*) AS total FROM page GROUP BY entry_state) a),
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'total',total,'counts',states)
       ORDER BY name),'[]'::jsonb) FROM
      (SELECT company_id AS id,max(company_name) AS name,count(*) AS total,
        jsonb_object_agg(entry_state,state_total) AS states FROM
        (SELECT company_id,company_name,entry_state,count(*) AS state_total FROM page
          GROUP BY company_id,company_name,entry_state) b GROUP BY company_id) c),
    (SELECT count(*) FROM filtered),
    (SELECT coalesce(jsonb_agg(entry ORDER BY sort),'[]'::jsonb) FROM (
       SELECT picked.ordinal AS sort,
         private_isg.ppe_handover_row(picked.handover_id,false)
           ||jsonb_build_object('company_name',picked.company_name) AS entry
       FROM (SELECT * FROM filtered ORDER BY ordinal LIMIT page_limit OFFSET page_offset) picked) built)
  INTO tally_all,tally_companies,matching_rows,tally_rows;

  RETURN jsonb_build_object('schema_version',1,'kind','list','rows',tally_rows,'today',today,
    'counts',tally_all,'companies',tally_companies,
    'total',matching_rows,'returned',jsonb_array_length(tally_rows),
    'has_more',page_offset+jsonb_array_length(tally_rows)<matching_rows,
    'limit',page_limit,'offset',page_offset,
    -- A tally of what is still out, never a statement that anyone is
    -- adequately protected.
    'compliance_verdict',NULL,'signed_copy_storage_available',false,
    'health_records_tracked',false);
END $$;

CREATE FUNCTION private_isg.mutate_ppe_handovers(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; allowed text[]; offending text; fingerprint bytea; prior private_isg.ppe_receipts;
  result jsonb; answer jsonb; handover uuid; entry private_isg.ppe_handovers;
  stamp timestamptz:=clock_timestamp(); today date;
BEGIN
  actor:=private_isg.require_ppe_company(p_company,true);
  IF p_action IS NULL OR p_operation IS NULL OR p_mutation IS NULL OR p_payload IS NULL OR
     jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>4096 THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(stamp AT TIME ZONE 'Europe/Istanbul')::date;
  allowed:=CASE p_action
    -- No `signed_copy` and no asset: the product holds no file, so the flag
    -- could only ever be refused. What may be recorded is where the signed
    -- form is kept.
    WHEN 'record_handover' THEN ARRAY['employee_id','item','quantity','unit','handed_on',
      'external_ref','signed_copy_location']
    WHEN 'record_return' THEN ARRAY['handover_id','quantity','returned_on','condition','note']
    WHEN 'remove_return' THEN ARRAY['handover_id','return_id']
    ELSE NULL END;
  IF allowed IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT key INTO offending FROM jsonb_object_keys(p_payload) AS keys(key)
    WHERE NOT (key=ANY(allowed)) ORDER BY key LIMIT 1;
  IF offending IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAYLOAD_NOT_ALLOWED'; END IF;

  fingerprint:=sha256(convert_to(jsonb_build_array(p_company,p_action,p_operation,p_payload)::text,'UTF8'));
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||':isg-ppe:'||p_mutation::text,0));
  SELECT * INTO prior FROM private_isg.ppe_receipts WHERE actor_id=actor AND mutation_id=p_mutation;
  IF FOUND THEN
    IF prior.request_hash IS DISTINCT FROM fingerprint THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='IDEMPOTENCY_CONFLICT'; END IF;
    RETURN prior.response||jsonb_build_object('replayed',true);
  END IF;

  IF p_action='record_handover' THEN
    IF p_payload->>'employee_id' IS NULL OR p_payload->>'item' IS NULL OR
       p_payload->>'quantity' IS NULL OR p_payload->>'unit' IS NULL OR
       p_payload->>'handed_on' IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    -- Nothing was handed over on a day that has not happened.
    IF (p_payload->>'handed_on')::date>today THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='HANDED_IN_THE_FUTURE'; END IF;
    answer:=private_isg.record_ppe_handover(p_company,(p_payload->>'employee_id')::uuid,
      p_payload->>'item',(p_payload->>'quantity')::numeric,p_payload->>'unit',
      (p_payload->>'handed_on')::date,NULL,false,
      nullif(btrim(coalesce(p_payload->>'external_ref','')),''),stamp);
    handover:=(answer->>'handover_id')::uuid;
    IF NOT coalesce((answer->>'replayed')::boolean,false) THEN
      UPDATE private_isg.ppe_handovers
        SET signed_copy_location=nullif(btrim(coalesce(p_payload->>'signed_copy_location','')),'')
        WHERE handover_id=handover;
    END IF;
  ELSE
    handover:=(p_payload->>'handover_id')::uuid;
    -- The handover has to be this company's before the core function, which
    -- was written for a caller that had already checked.
    SELECT * INTO entry FROM private_isg.ppe_handovers
      WHERE handover_id=handover AND company_id=p_company FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    IF p_action='record_return' THEN
      IF p_payload->>'quantity' IS NULL OR p_payload->>'returned_on' IS NULL OR
         p_payload->>'condition' IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
      IF (p_payload->>'returned_on')::date>today THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='RETURNED_IN_THE_FUTURE'; END IF;
      answer:=private_isg.record_ppe_return(handover,(p_payload->>'quantity')::numeric,
        (p_payload->>'returned_on')::date,p_payload->>'condition',
        nullif(btrim(coalesce(p_payload->>'note','')),''),stamp);
    ELSE
      IF p_payload->>'return_id' IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
      answer:=private_isg.remove_ppe_return(handover,(p_payload->>'return_id')::uuid);
    END IF;
  END IF;

  result:=jsonb_build_object('schema_version',1,'action',p_action,'handover_id',handover,'answer',answer,
    'row',private_isg.ppe_handover_row(handover,true));
  INSERT INTO private_isg.ppe_receipts(actor_id,mutation_id,company_id,operation_id,request_hash,response)
    VALUES(actor,p_mutation,p_company,p_operation,fingerprint,result);
  RETURN result||jsonb_build_object('replayed',false);
END $$;

CREATE FUNCTION public.isg_ppe_read_v1(p_company uuid,p_kind text,p_query text,p_state text,
  p_employee uuid,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.read_ppe_handovers(p_company,p_kind,p_query,p_state,p_employee,p_id,p_limit,p_offset)
$$;
CREATE FUNCTION public.isg_ppe_mutate_v1(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.mutate_ppe_handovers(p_company,p_action,p_operation,p_mutation,p_payload)
$$;

REVOKE ALL ON FUNCTION private_isg.ppe_handover_status(numeric,numeric),
  private_isg.ppe_gate(boolean),
  private_isg.require_ppe_company(uuid,boolean),
  private_isg.remove_ppe_return(uuid,uuid),
  private_isg.ppe_handover_row(uuid,boolean),
  private_isg.read_ppe_handovers(uuid,text,text,text,uuid,uuid,integer,integer),
  private_isg.mutate_ppe_handovers(uuid,text,uuid,uuid,jsonb),
  public.isg_ppe_read_v1(uuid,text,text,text,uuid,uuid,integer,integer),
  public.isg_ppe_mutate_v1(uuid,text,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION private_isg.read_ppe_handovers(uuid,text,text,text,uuid,uuid,integer,integer),
  private_isg.mutate_ppe_handovers(uuid,text,uuid,uuid,jsonb),
  public.isg_ppe_read_v1(uuid,text,text,text,uuid,uuid,integer,integer),
  public.isg_ppe_mutate_v1(uuid,text,uuid,uuid,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';


-- P10 client slice: the surface behind "Atama ve Temsilciler".
-- Additive. No rollout row is added and none is opened: this rides on the
-- `modules` feature and the `appointment` module switch P10 already created.
--
-- The P10 core built the appointment, its ending, and the one rule that matters:
-- the same person cannot hold two overlapping appointments of the same kind in
-- the same scope, enforced by an exclusion constraint rather than by a check
-- anyone can forget. Two things were missing rather than merely unreachable:
--
--   1. No client boundary, and no ownership check. `module_scope` proves the
--      workplace belongs to the company, never that the company belongs to the
--      caller.
--   2. The plan lists the basis of an appointment among its fields — a worker
--      representative is elected, support staff are appointed — and there was
--      no column for it, nor for where the appointment letter is kept.
--
-- Five things this slice makes structurally impossible:
--   1. Another owner's appointment, employee or workplace cannot be reached.
--   2. The same person cannot hold two overlapping appointments of the same
--      kind in the same scope. The constraint owns that rule; correcting an
--      end date is guarded by the same constraint rather than by a second
--      check written beside it.
--   3. Nobody is ever labelled qualified for a role. There is no field for it,
--      the schema has nowhere to put one, and every read says so.
--   4. The product never says how many representatives or support staff a
--      workplace needs. No approved count catalogue exists, so the read
--      reports that the required number is unknown rather than implying zero
--      or enough.
--   5. An appointment cannot end before it began, and ending it is a change to
--      that appointment, never a new one. Correcting an end date goes through
--      the same exclusion constraint, so it cannot be stretched over the
--      person's next appointment in the same role.
SET LOCAL lock_timeout='5s';

-- Why this person holds the role, and where the letter is. A representative is
-- elected by the workers; support staff are appointed by the employer. Saying
-- which is the point of the field, so the boundary demands it.
ALTER TABLE private_isg.appointments
  ADD COLUMN basis text CHECK(basis IS NULL OR basis IN ('elected','appointed')),
  ADD COLUMN basis_note text CHECK(basis_note IS NULL OR length(basis_note)<=500),
  -- The tracker holds a reference, never the letter itself.
  ADD COLUMN letter_location text CHECK(letter_location IS NULL OR length(letter_location)<=300);

CREATE TABLE private_isg.appointment_receipts (
  actor_id uuid NOT NULL, mutation_id uuid NOT NULL, company_id uuid NOT NULL,
  operation_id uuid NOT NULL, request_hash bytea NOT NULL, response jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,mutation_id),
  FOREIGN KEY(company_id,actor_id) REFERENCES public.companies(id,user_id) ON DELETE CASCADE
);
CREATE INDEX appointment_receipt_company_idx ON private_isg.appointment_receipts(company_id,actor_id);
ALTER TABLE private_isg.appointment_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA private_isg FROM PUBLIC,anon,authenticated,service_role;

-- The kinds an appointment can be, as the schema already fixes them. A table so
-- the client is offered exactly what the server accepts.
CREATE TABLE private_isg.appointment_kinds (
  kind text PRIMARY KEY CHECK(kind IN ('representative','support_staff','team_member','first_aid','fire_team')),
  ordinal integer NOT NULL CHECK(ordinal BETWEEN 1 AND 99),
  -- Which basis the product expects for this kind. A suggestion for the form,
  -- never a rule: the expert states what actually happened.
  usual_basis text NOT NULL CHECK(usual_basis IN ('elected','appointed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(ordinal)
);
INSERT INTO private_isg.appointment_kinds(kind,ordinal,usual_basis) VALUES
  ('representative',1,'elected'),('support_staff',2,'appointed'),('team_member',3,'appointed'),
  ('first_aid',4,'appointed'),('fire_team',5,'appointed');
ALTER TABLE private_isg.appointment_kinds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA private_isg FROM PUBLIC,anon,authenticated,service_role;

-- Where an appointment stands today. Nothing is stored: the answer comes from
-- its own dates at read time, so no row can carry yesterday's answer.
CREATE FUNCTION private_isg.appointment_status(p_starts_on date,p_ends_before date,p_today date) RETURNS text
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
BEGIN
  IF p_starts_on>p_today THEN RETURN 'upcoming'; END IF;
  IF p_ends_before IS NOT NULL AND p_ends_before<=p_today THEN RETURN 'ended'; END IF;
  RETURN 'active';
END $$;

CREATE FUNCTION private_isg.appointment_gate(p_write boolean) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
  PERFORM private_isg.module_gate('appointment',p_write);
END $$;

CREATE FUNCTION private_isg.require_appointment_company(p_company uuid,p_write boolean) RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=private_isg.active_actor();
BEGIN
  IF NOT private_isg.p05_pilot_account_enabled(actor,p_write) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='FEATURE_UNAVAILABLE'; END IF;
  IF p_company IS NOT NULL AND NOT private_isg.p05_pilot_can_read(actor,p_company) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  PERFORM private_isg.appointment_gate(p_write);
  IF p_write THEN
    IF p_company IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM public.user_subscriptions WHERE user_id=actor AND tier IN ('plus','pro') AND
      status IN ('active','trialing','grace_period') AND
      (current_period_ends_at IS NULL OR current_period_ends_at>clock_timestamp()) FOR SHARE;
    IF NOT FOUND OR private.user_plan_tier(actor) NOT IN ('plus','pro') THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAID_PLAN_REQUIRED'; END IF;
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor AND NOT is_archived FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSIF p_company IS NOT NULL THEN
    PERFORM 1 FROM public.companies WHERE id=p_company AND user_id=actor FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor) THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
  END IF;
  RETURN actor;
END $$;

-- One appointment as the board sees it.
CREATE FUNCTION private_isg.appointment_row(p_appointment uuid,p_today date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE entry private_isg.appointments; person private_isg.employees;
  place private_isg.workplaces; usual text; shown_state text;
BEGIN
  SELECT * INTO entry FROM private_isg.appointments WHERE appointment_id=p_appointment;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO person FROM private_isg.employees
    WHERE company_id=entry.company_id AND id=entry.employee_id;
  SELECT * INTO place FROM private_isg.workplaces
    WHERE company_id=entry.company_id AND id=entry.scope_workplace_id;
  SELECT usual_basis INTO usual FROM private_isg.appointment_kinds WHERE kind=entry.kind;
  shown_state:=private_isg.appointment_status(entry.starts_on,entry.ends_before,p_today);
  RETURN jsonb_build_object(
    'id',entry.appointment_id,'company_id',entry.company_id,
    'employee_id',entry.employee_id,'employee_name',person.full_name,
    'employee_archived',coalesce(person.is_archived,false),
    'workplace_id',entry.scope_workplace_id,'workplace_name',place.name,
    'kind',entry.kind,'usual_basis',usual,
    'starts_on',entry.starts_on,'ends_before',entry.ends_before,
    'state',shown_state,'state_authority','computed_at_read',
    'basis',entry.basis,'basis_note',entry.basis_note,
    -- The product holds no letter, only a note of where it is.
    'letter_location',entry.letter_location,'letter_stored',false,
    -- No legal condition was checked, and there is nowhere to record that one
    -- was. Holding a role is not the same as being qualified for it.
    'qualification_verified',false,
    -- No approved catalogue says how many a workplace needs.
    'required_count_known',false,
    'compliance_verdict',NULL,'health_records_tracked',false);
END $$;

CREATE FUNCTION private_isg.read_appointments(p_company uuid,p_kind text,p_query text,p_state text,
  p_workplace uuid,p_role text,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; needle text; today date;
  page_limit integer; page_offset integer;
  tally_all jsonb; tally_companies jsonb; tally_rows jsonb; matching_rows integer;
BEGIN
  actor:=private_isg.require_appointment_company(p_company,false);
  IF p_kind IS NULL OR p_kind NOT IN ('catalog','list','detail') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(clock_timestamp() AT TIME ZONE 'Europe/Istanbul')::date;

  IF p_kind='catalog' THEN
    RETURN jsonb_build_object('schema_version',1,'kind','catalog',
      'kinds',(SELECT coalesce(jsonb_agg(jsonb_build_object('code',k.kind,'ordinal',k.ordinal,
          'usual_basis',k.usual_basis) ORDER BY k.ordinal),'[]'::jsonb)
        FROM private_isg.appointment_kinds k),
      'bases',jsonb_build_array('elected','appointed'),
      'workplaces',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',w.id,'name',w.name)
          ORDER BY w.name),'[]'::jsonb)
        FROM private_isg.workplaces w
        WHERE p_company IS NOT NULL AND w.company_id=p_company AND w.owner_id=actor AND NOT w.is_archived),
      'employees',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'full_name',e.full_name)
          ORDER BY e.full_name),'[]'::jsonb)
        FROM private_isg.employees e
        WHERE p_company IS NOT NULL AND e.company_id=p_company AND NOT e.is_archived),
      -- Said plainly rather than left to be inferred from a silent screen.
      'required_count_known',false,
      'qualification_check_available',false,
      'letter_storage_available',false,
      'health_records_tracked',false);
  END IF;

  IF p_kind='detail' THEN
    IF p_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    PERFORM 1 FROM private_isg.appointments a
      JOIN public.companies c ON c.id=a.company_id AND c.user_id=actor
      WHERE a.appointment_id=p_id AND (p_company IS NULL OR a.company_id=p_company);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    RETURN jsonb_build_object('schema_version',1,'kind','detail','today',today,
      'row',private_isg.appointment_row(p_id,today));
  END IF;

  IF p_state IS NOT NULL AND p_state NOT IN ('upcoming','active','ended') THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  IF p_role IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private_isg.appointment_kinds WHERE kind=p_role) THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  page_limit:=least(greatest(coalesce(p_limit,10),1),100);
  page_offset:=greatest(coalesce(p_offset,0),0);
  needle:=nullif(btrim(coalesce(p_query,'')),'');

  WITH scope AS (
    SELECT c.id,c.name FROM public.companies c WHERE c.user_id=actor AND NOT c.is_archived AND private_isg.p05_pilot_can_read(actor,c.id)
  ), page AS (
    SELECT a.appointment_id,a.company_id,s.name AS company_name,a.employee_id,e.full_name AS employee_name,
      a.scope_workplace_id,w.name AS workplace_name,a.kind AS role_kind,a.starts_on,
      private_isg.appointment_status(a.starts_on,a.ends_before,today) AS entry_state,
      -- Active first, then what is about to begin, then what is over.
      row_number() OVER (ORDER BY
        CASE private_isg.appointment_status(a.starts_on,a.ends_before,today)
          WHEN 'active' THEN 0 WHEN 'upcoming' THEN 1 ELSE 2 END,
        a.starts_on DESC,s.name,w.name,e.full_name,a.appointment_id) AS ordinal
    FROM private_isg.appointments a
    JOIN scope s ON s.id=a.company_id
    JOIN private_isg.employees e ON e.company_id=a.company_id AND e.id=a.employee_id
    JOIN private_isg.workplaces w ON w.company_id=a.company_id AND w.id=a.scope_workplace_id
    WHERE w.owner_id=actor AND NOT w.is_archived
  ), scoped AS (
    SELECT * FROM page WHERE (p_company IS NULL OR company_id=p_company)
  ), filtered AS (
    SELECT * FROM scoped
    WHERE (p_workplace IS NULL OR scope_workplace_id=p_workplace)
      AND (p_role IS NULL OR role_kind=p_role)
      AND (p_state IS NULL OR entry_state=p_state)
      AND (needle IS NULL OR employee_name ILIKE '%'||needle||'%'
           OR workplace_name ILIKE '%'||needle||'%' OR company_name ILIKE '%'||needle||'%')
  )
  SELECT
    (SELECT coalesce(jsonb_object_agg(state,total),'{}'::jsonb) FROM
      (SELECT entry_state AS state,count(*) AS total FROM page GROUP BY entry_state) a),
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'total',total,'counts',states)
       ORDER BY name),'[]'::jsonb) FROM
      (SELECT company_id AS id,max(company_name) AS name,count(*) AS total,
        jsonb_object_agg(entry_state,state_total) AS states FROM
        (SELECT company_id,company_name,entry_state,count(*) AS state_total FROM page
          GROUP BY company_id,company_name,entry_state) b GROUP BY company_id) c),
    (SELECT count(*) FROM filtered),
    (SELECT coalesce(jsonb_agg(entry ORDER BY sort),'[]'::jsonb) FROM (
       SELECT picked.ordinal AS sort,
         private_isg.appointment_row(picked.appointment_id,today)
           ||jsonb_build_object('company_name',picked.company_name) AS entry
       FROM (SELECT * FROM filtered ORDER BY ordinal LIMIT page_limit OFFSET page_offset) picked) built)
  INTO tally_all,tally_companies,matching_rows,tally_rows;

  RETURN jsonb_build_object('schema_version',1,'kind','list','rows',tally_rows,'today',today,
    'counts',tally_all,'companies',tally_companies,
    'total',matching_rows,'returned',jsonb_array_length(tally_rows),
    'has_more',page_offset+jsonb_array_length(tally_rows)<matching_rows,
    'limit',page_limit,'offset',page_offset,
    -- A tally of who holds which role, never a statement that a workplace has
    -- enough of them or that anyone is qualified.
    'compliance_verdict',NULL,'required_count_known',false,
    'qualification_check_available',false,'health_records_tracked',false);
END $$;

CREATE FUNCTION private_isg.mutate_appointments(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; allowed text[]; offending text; fingerprint bytea; prior private_isg.appointment_receipts;
  result jsonb; answer jsonb; appointment uuid; entry private_isg.appointments;
  stamp timestamptz:=clock_timestamp(); today date;
BEGIN
  actor:=private_isg.require_appointment_company(p_company,true);
  IF p_action IS NULL OR p_operation IS NULL OR p_mutation IS NULL OR p_payload IS NULL OR
     jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>4096 THEN
    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  today:=(stamp AT TIME ZONE 'Europe/Istanbul')::date;
  allowed:=CASE p_action
    -- No qualification field of any kind: holding a role is not being
    -- qualified for it, and nothing here may say otherwise.
    WHEN 'record_appointment' THEN ARRAY['employee_id','kind','workplace_id','starts_on','ends_before',
      'basis','basis_note','letter_location']
    WHEN 'end_appointment' THEN ARRAY['appointment_id','ends_before']
    ELSE NULL END;
  IF allowed IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
  SELECT key INTO offending FROM jsonb_object_keys(p_payload) AS keys(key)
    WHERE NOT (key=ANY(allowed)) ORDER BY key LIMIT 1;
  IF offending IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='PAYLOAD_NOT_ALLOWED'; END IF;

  fingerprint:=sha256(convert_to(jsonb_build_array(p_company,p_action,p_operation,p_payload)::text,'UTF8'));
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||':isg-appointment:'||p_mutation::text,0));
  SELECT * INTO prior FROM private_isg.appointment_receipts WHERE actor_id=actor AND mutation_id=p_mutation;
  IF FOUND THEN
    IF prior.request_hash IS DISTINCT FROM fingerprint THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='IDEMPOTENCY_CONFLICT'; END IF;
    RETURN prior.response||jsonb_build_object('replayed',true);
  END IF;

  IF p_action='record_appointment' THEN
    IF p_payload->>'employee_id' IS NULL OR p_payload->>'kind' IS NULL OR
       p_payload->>'workplace_id' IS NULL OR p_payload->>'starts_on' IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    -- Saying why the person holds the role is the point of the field.
    IF p_payload->>'basis' IS NULL OR p_payload->>'basis' NOT IN ('elected','appointed') THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='BASIS_REQUIRED'; END IF;
    PERFORM 1 FROM private_isg.workplaces WHERE company_id=p_company
      AND id=(p_payload->>'workplace_id')::uuid AND owner_id=actor AND NOT is_archived;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    answer:=private_isg.record_appointment(p_company,(p_payload->>'employee_id')::uuid,
      p_payload->>'kind',(p_payload->>'workplace_id')::uuid,
      (p_payload->>'starts_on')::date,(p_payload->>'ends_before')::date,NULL,stamp);
    appointment:=(answer->>'appointment_id')::uuid;
    UPDATE private_isg.appointments SET basis=p_payload->>'basis',
      basis_note=nullif(btrim(coalesce(p_payload->>'basis_note','')),''),
      letter_location=nullif(btrim(coalesce(p_payload->>'letter_location','')),'')
      WHERE appointment_id=appointment;
  ELSE
    appointment:=(p_payload->>'appointment_id')::uuid;
    SELECT * INTO entry FROM private_isg.appointments
      WHERE appointment_id=appointment AND company_id=p_company FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCESS_DENIED'; END IF;
    IF p_payload->>'ends_before' IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='VALIDATION_ERROR'; END IF;
    answer:=private_isg.end_appointment(appointment,(p_payload->>'ends_before')::date,stamp);
  END IF;

  result:=jsonb_build_object('schema_version',1,'action',p_action,'appointment_id',appointment,
    'answer',answer,'row',private_isg.appointment_row(appointment,today));
  INSERT INTO private_isg.appointment_receipts(actor_id,mutation_id,company_id,operation_id,request_hash,response)
    VALUES(actor,p_mutation,p_company,p_operation,fingerprint,result);
  RETURN result||jsonb_build_object('replayed',false);
END $$;

CREATE FUNCTION public.isg_appointments_read_v1(p_company uuid,p_kind text,p_query text,p_state text,
  p_workplace uuid,p_role text,p_id uuid,p_limit integer,p_offset integer) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.read_appointments(p_company,p_kind,p_query,p_state,p_workplace,p_role,p_id,p_limit,p_offset)
$$;
CREATE FUNCTION public.isg_appointments_mutate_v1(p_company uuid,p_action text,p_operation uuid,
  p_mutation uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
  SELECT private_isg.mutate_appointments(p_company,p_action,p_operation,p_mutation,p_payload)
$$;

REVOKE ALL ON FUNCTION private_isg.appointment_status(date,date,date),
  private_isg.appointment_gate(boolean),
  private_isg.require_appointment_company(uuid,boolean),
  private_isg.appointment_row(uuid,date),
  private_isg.read_appointments(uuid,text,text,text,uuid,text,uuid,integer,integer),
  private_isg.mutate_appointments(uuid,text,uuid,uuid,jsonb),
  public.isg_appointments_read_v1(uuid,text,text,text,uuid,text,uuid,integer,integer),
  public.isg_appointments_mutate_v1(uuid,text,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION private_isg.read_appointments(uuid,text,text,text,uuid,text,uuid,integer,integer),
  private_isg.mutate_appointments(uuid,text,uuid,uuid,jsonb),
  public.isg_appointments_read_v1(uuid,text,text,text,uuid,text,uuid,integer,integer),
  public.isg_appointments_mutate_v1(uuid,text,uuid,uuid,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';


REVOKE ALL ON private_isg.emergency_plan_versions FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.drill_records FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.appointments FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.ppe_handovers FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.ppe_returns FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.emergency_plan_receipts FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.emergency_team_roles FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.drill_receipts FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.ppe_receipts FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.appointment_receipts FROM PUBLIC,anon,authenticated,service_role;

REVOKE ALL ON private_isg.appointment_kinds FROM PUBLIC,anon,authenticated,service_role;

NOTIFY pgrst,'reload schema';
